<?php trait T{public static ?self $s;public ?self $x;}trait U{use T;}trait V{public static ?self $s;public ?self $x;}class A{use T;}class B extends A{use U;}class C extends A{use V;}$a=new A;$b=new B;$c=new C;$a->x=$a;$b->x=$b;$c->x=$c;A::$s=$a;B::$s=$b;C::$s=$c;echo get_class(A::$s),get_class(B::$s),get_class(C::$s),get_class($b->x),get_class($c->x);try{B::$s=$a;}catch(Throwable $e){echo $e->getMessage();}
